mapper.update:
UPDATE session_info
SET
    end_time = #{endTime,jdbcType=TIMESTAMP},
    status = #{status,jdbcType=VARCHAR,typeHandler=org.apache.ibatis.type.EnumTypeHandler}
WHERE session_count = #{sessionCount,jdbcType=BIGINT}

mapper.select:
SELECT id, session_count, start_time, end_time, status, created_at, updated_at
FROM session_info
WHERE session_count = #{sessionCount,jdbcType=BIGINT}
